    if m == 0 or n == 0:
        return 0
    elif seq1[m-1] == seq2[n-1]:
        return 1 + longest_common_subsequence(seq1, seq2, m-1, n-1)
    else:
        return max(longest_common_subsequence(seq1, seq2, m, n-1), longest_common_subsequence(seq1, seq2, m-1, n))
```

