def heap_replace(heap, new_item):
    # Replace the smallest element (root) with the new item
    heap[0] = new_item
    # Restore the heap property by sifting down the root
    sift_down(heap)
    return heap

def sift_down(heap):
    n = len(heap)
    for i in range(n // 2 - 1, -1, -1):
        sift_up(heap, i)

def sift_up(heap, i):
    while i > 0 and heap[i] < heap[(i - 1) // 2]:
        heap[i], heap[(i - 1) // 2] = heap[(i - 1) // 2], heap[i]
        i = (i - 1) // 2
```

